import { Handler } from '@zcatalyst/transport';
import { CONSTANTS, isNonEmptyObject, isNonEmptyString, isValidInputString, ObjectHasProperties, wrapValidators, wrapValidatorsWithPromise } from '@zcatalyst/utils';
import pkg from '../package.json' with { type: 'json' };
const { version } = pkg;
import { Table, TableAdmin } from './table.js';
import { CatalystDataStoreError } from './utils/error.js';
const { REQ_METHOD, CREDENTIAL_USER, COMPONENT, ACCEPT_HEADER } = CONSTANTS;
export class Datastore {
    constructor(app) {
        this.requester = new Handler(app, this);
    }
    getComponentName() {
        return COMPONENT.datastore;
    }
    getComponentVersion() {
        return version;
    }
    table(id) {
        wrapValidators(() => {
            isValidInputString(id, 'table_id/table_name', true);
        }, CatalystDataStoreError);
        if (!parseInt(id + '')) {
            return new Table(this, { table_name: id + '' });
        }
        return new Table(this, { table_id: id + '' });
    }
    async executeZCQLQuery(query) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(query, 'query', true);
        }, CatalystDataStoreError);
        const request = {
            method: REQ_METHOD.post,
            path: '/query',
            data: { query },
            type: "json",
            expecting: "json",
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.user,
            headers: {
                [ACCEPT_HEADER.KEY]: ACCEPT_HEADER.ZCQL
            }
        };
        const resp = await this.requester.send(request);
        return resp.data.data;
    }
    async executeOLAPQuery(query) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(query, 'query', true);
        }, CatalystDataStoreError);
        const request = {
            method: REQ_METHOD.post,
            path: '/query',
            data: { query, OLAP: true },
            type: "json",
            expecting: "json",
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.user,
            headers: {
                [ACCEPT_HEADER.KEY]: ACCEPT_HEADER.ZCQL
            }
        };
        const resp = await this.requester.send(request);
        return resp.data.data;
    }
    async executeSearchQuery(searchQuery) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyObject(searchQuery, 'search_object', true);
            ObjectHasProperties(searchQuery, ['search', 'search_table_columns'], 'search_object', true);
        }, CatalystDataStoreError);
        const request = {
            method: REQ_METHOD.post,
            path: `/search`,
            data: searchQuery,
            type: "json",
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.user
        };
        const resp = await this.requester.send(request);
        return resp.data.data;
    }
}
export class DatastoreAdmin extends Datastore {
    constructor(app) {
        super(app);
    }
    async getAllTables() {
        const request = {
            method: REQ_METHOD.get,
            path: `/table`,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const resp = await this.requester.send(request);
        const jsonArr = resp.data.data;
        const tableArr = [];
        jsonArr.forEach((table) => {
            tableArr.push(new Table(this, table));
        });
        return tableArr;
    }
    async getTableDetails(id) {
        await wrapValidatorsWithPromise(() => {
            isValidInputString(id, 'table_id', true);
        }, CatalystDataStoreError);
        const request = {
            method: REQ_METHOD.get,
            path: `/table/${id}`,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const resp = await this.requester.send(request);
        const json = resp.data.data;
        return new Table(this, json);
    }
    table(id) {
        wrapValidators(() => {
            isValidInputString(id, 'table_id/table_name', true);
        }, CatalystDataStoreError);
        if (!parseInt(id + '')) {
            return new TableAdmin(this, { table_name: id + '' });
        }
        return new TableAdmin(this, { table_id: id + '' });
    }
}
